type Usuario = { id: number; nombre: string };

function esUsuario(valor: unknown): valor is Usuario {
  return typeof valor === "object" && valor !== null &&
    "id" in valor && typeof valor.id === "number" &&
    "nombre" in valor && typeof valor.nombre === "string";
}

async function cargarUsuario(id: number): Promise<Usuario> {
  const respuesta = await fetch("/api/usuarios/" + id);
  if (!respuesta.ok) throw new Error("HTTP " + respuesta.status);
  const dato: unknown = await respuesta.json();
  if (!esUsuario(dato)) throw new Error("Respuesta inválida");
  return dato;
}

async function cargarDatos() {
  try {
    const respuesta = await fetch("/datos.json");
    if (!respuesta.ok) throw new Error("HTTP " + respuesta.status);
    return await respuesta.json();
  } catch (error: unknown) {
    if (error instanceof Error) console.error(error.message);
    else console.error("Error desconocido");
    throw error;
  }
}

